        break;
    case SIM_EXIST_STATUS_SIM2 :
        lv_obj_clear_flag(ui_PnlSim, LV_OBJ_FLAG_HIDDEN);
        lv_dropdown_clear_options(ui_DrpdwnSelectSim);
        lv_dropdown_set_options(ui_DrpdwnSelectSim, "SIM2");
        lv_label_set_text(ui_LblSimIMSI, show_imsi_txt);
        break;
    case SIM_EXIST_STATUS_BOTH :
        lv_obj_clear_flag(ui_PnlSim, LV_OBJ_FLAG_HIDDEN);
        lv_dropdown_clear_options(ui_DrpdwnSelectSim);
        lv_dropdown_set_options(ui_DrpdwnSelectSim, "SIM1\nSIM2");
        lv_dropdown_set_selected(ui_DrpdwnSelectSim, card_id);
        lv_label_set_text(ui_LblSimIMSI, show_imsi_txt);
        break;
    default:
