void phone_win_active(lv_obj_t *win, void *p_param)
{
    ui_phone_init();

    lv_group_add_obj(lv_group_get_default(), ui_PnlFlightMode);
    lv_group_add_obj(lv_group_get_default(), ui_PnlVolteMode);
    lv_group_add_obj(lv_group_get_default(), ui_PnlSim);
    lv_group_focus_obj(ui_PnlFlightMode);
}
void phone_win_deactive(lv_obj_t *win, void *p_param)
{
    lv_obj_del(ui_Phone);
}
void phone_win_focus(lv_obj_t *win, void *p_param)
{
    softkey_t softkey_right = {0};
    softkey_t softkey_left = {0};

    lv_disp_load_scr(ui_Phone);
    lv_obj_t *obj = lv_obj_get_user_data(ui_Phone);
    if(NULL == obj) {
        obj = ui_PnlFlightMode;
    }
    lv_group_focus_obj(obj);

    SHOW_STATUSBAR_SUB_WIN("Phone");
    softkey_left.p_txt = "Enter";
    softkey_right.p_txt = "Back";
    SHOW_SOFTKEY(&softkey_left, NULL, &softkey_right);

    phone_fresh_flightmode();
    phone_fresh_voltemode();
    phone_fresh_selectsim();
}
void phone_win_defocus(lv_obj_t *win, void *p_param)
{
    lv_obj_t *obj = lv_group_get_focused(lv_group_get_default());
    lv_obj_set_user_data(ui_Phone, obj);
}

