void PhonePnlFlightModeKey(lv_event_t * e)
{
	// Your code here
    uint32_t key = lv_event_get_key(e);
    switch (key) {
    case LV_KEY_BACKSPACE:
        lv_indev_wait_release(lv_indev_get_act());
        alv_am_win_exit(NULL, "phone", NULL);
        break;
    case LV_KEY_ENTER:
    case LV_KEY_HOME:
        _ui_state_modify(ui_SwitchFlightMode, LV_STATE_CHECKED, _UI_MODIFY_STATE_TOGGLE);
        lv_event_send(ui_SwitchFlightMode, LV_EVENT_VALUE_CHANGED, NULL);
        break;
    case LV_KEY_DOWN:
        lv_group_focus_obj(ui_PnlVolteMode);
        break;
    case LV_KEY_UP:
        /*Focus the last object, Adjust the code with UI update*/
        if(false == lv_obj_has_flag(ui_PnlSim, LV_OBJ_FLAG_HIDDEN)) {
            lv_group_focus_obj(ui_PnlSim);
        } else {
            lv_group_focus_obj(ui_PnlVolteMode);
        }
        break;
    default:
        LV_LOG_WARN("there is no event for the key(%ld)", key);
        break;
    }
}

