    case LV_KEY_UP:
        if(false == lv_dropdown_is_open(ui_DrpdwnSelectSim)) {
            lv_group_focus_obj(ui_PnlVolteMode);
        } else {
            lv_event_send(ui_DrpdwnSelectSim, LV_EVENT_KEY, &key);
        }
